package org.eclipse.rdf4j.query.algebra.evaluation.impl;

import static org.junit.jupiter.api.Assertions.assertThrows;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryValueEvaluationStep;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.evaluationsteps.values.QueryValueEvaluationStepSupplier;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.junit.jupiter.api.Test;

class BlankNodeFunctionArgumentReferenceTest {
	@Test
	void dynamicBnodeArgumentMustBeStringLiteral() {
		var vf = SimpleValueFactory.getInstance();
		var bindings = new MapBindingSet();
		bindings.addBinding("node", vf.createBNode("known"));
		var dynamic = new QueryValueEvaluationStep.ApplyFunctionForEachBinding(bs -> bs.getValue("node"));
		var bnode = QueryValueEvaluationStepSupplier.bnode(dynamic, vf, new QueryEvaluationContext.Minimal(null));
		assertThrows(ValueExprEvaluationException.class, () -> bnode.evaluate(bindings));
	}
}
